import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.DncwoWA8.js";const u=JSON.parse('{"title":"Supporting tools and other workflows","description":"","frontmatter":{"title":"Supporting tools and other workflows"},"headers":[],"relativePath":"workflows/supporting-tools.md","filePath":"workflows/supporting-tools.md"}'),o={name:"workflows/supporting-tools.md"};function n(r,e,l,p,c,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="supporting-tools-and-other-workflows" tabindex="-1">Supporting tools and other workflows <a class="header-anchor" href="#supporting-tools-and-other-workflows" aria-label="Permalink to &quot;Supporting tools and other workflows&quot;">​</a></h1><p>Use these tools around the <a href="/projects/ai-skills/workflows/">five project workflows</a>. They provide setup, clarification, execution safeguards, or a separate bounded result. They are not extra stages that every project must complete.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ol><li>Read the target project&#39;s instructions and confirm the requested result and permitted actions.</li><li>Check the selected skills&#39; profiles and authoritative instructions. Follow <a href="/projects/ai-skills/guide/install.html">installation choices</a> for missing skills rather than assuming a website listing installs them.</li><li>Resolve declared instruction requirements separately from runtime tools and harness capabilities. If a selected skill or requirement is missing, stop the task, list the missing names, and ask the user to install them. Do not fetch, synchronize, substitute, delegate, or continue without those instructions. Resume only after installation is confirmed and availability is verified.</li><li>Confirm the output destination, workspace requirements, checks, and authority for actions that write state.</li></ol><p>A <code>/skill-name</code> label in a diagram identifies a skill, not a portable invocation. These guides use prompts as examples, not shell commands or portable slash commands. Load the intended installed skill through your harness, then adapt the prompt to the target project. Harness-specific loading is described in <a href="/projects/ai-skills/guide/first-use.html">first use</a>.</p><p>Arrows show possible handoffs. They do not change <code>requires</code> declarations or grant authority for a later phase. See <a href="/projects/ai-skills/reference/relationships.html">relationship types</a>.</p><h2 id="workspace-safeguards-and-setup" tabindex="-1">Workspace safeguards and setup <a class="header-anchor" href="#workspace-safeguards-and-setup" aria-label="Permalink to &quot;Workspace safeguards and setup&quot;">​</a></h2><p>Apply the target project&#39;s workspace policy before mutation. Use <a href="/projects/ai-skills/skills/isolated-workspace.html"><code>isolated-workspace</code></a> where selected or required, and use <a href="/projects/ai-skills/skills/cleanup-workspaces.html"><code>cleanup-workspaces</code></a> only for separately authorized cleanup.</p><p>These safeguards protect planning records, source edits, documentation, and other writes alike. They belong around execution rather than inside each product-flow diagram. This repository requires isolation before mutation.</p><p>Focused procedures:</p><ul><li><a href="/projects/ai-skills/workflows/protect-a-change.html">Prepare a change workspace</a>.</li><li><a href="/projects/ai-skills/workflows/clean-integrated-workspaces.html">Clean proven, approved workspaces</a>.</li><li><a href="/projects/ai-skills/workflows/install-selected-skills.html">Install a reviewed skill selection</a>.</li><li><a href="/projects/ai-skills/workflows/initialize-a-project.html">Initialize only an approved project foundation</a>.</li></ul><p>Installing skills does not initialize a project. Initializing a project does not authorize feature work. The reviewed-selection manager is a separate, explicitly requested tool, not a prerequisite, companion, handoff, or missing-skill recovery step for these workflows.</p><h2 id="clarification-and-explanation" tabindex="-1">Clarification and explanation <a class="header-anchor" href="#clarification-and-explanation" aria-label="Permalink to &quot;Clarification and explanation&quot;">​</a></h2><p>Use <a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a> to settle unresolved decisions or stress-test a plan when selected. Reuse confirmed answers and inspect available project facts before asking the user.</p><p>The current <code>research</code>, <code>initiative</code>, and <code>specify</code> skills declare <code>grilling</code> as required instructions. The interview itself is contextual, but loading the declared requirement is not optional. Changing that dependency needs a separate approved skill change.</p><p>Use <a href="/projects/ai-skills/skills/wait-what.html"><code>wait-what</code></a> when an explanation needs simpler language or missing context. For focused procedures, see <a href="/projects/ai-skills/workflows/challenge-a-design.html">challenge a plan</a> and <a href="/projects/ai-skills/workflows/re-pitch-an-explanation.html">ask for a clearer explanation</a>.</p><h2 id="authorized-delegation" tabindex="-1">Authorized delegation <a class="header-anchor" href="#authorized-delegation" aria-label="Permalink to &quot;Authorized delegation&quot;">​</a></h2><p>Use <a href="/projects/ai-skills/skills/subagent-orchestration.html"><code>subagent-orchestration</code></a> when the operator authorizes specialists, independent review, or parallel work. Define bounded tasks, ownership, allowed writes, integration checks, and capacity limits.</p><p>Delegation is an execution choice, not a mandatory step between planning and coding. A task list alone does not authorize launching workers.</p><p>See <a href="/projects/ai-skills/workflows/delegate-bounded-work.html">delegate bounded work</a> or <a href="/projects/ai-skills/workflows/coordinate-read-only-review.html">coordinate read-only review</a>. Keep direct execution as an available route.</p><h2 id="review-an-existing-change" tabindex="-1">Review an existing change <a class="header-anchor" href="#review-an-existing-change" aria-label="Permalink to &quot;Review an existing change&quot;">​</a></h2><p>An existing branch or change can enter review without repeating planning or implementation.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Fixed comparison and requirements</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>code-review: Standards and Spec</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Findings and verification limits</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Stop, or authorize corrections</span></span></code></pre></div><p><a href="/projects/ai-skills/skills/code-review.html"><code>code-review</code></a> requires Git and a harness that supports parallel read-only reviewers. Confirm delegation authority and capacity before launching them. Pin the comparison and provide the same immutable endpoints to both reviewers.</p><p>The current skill reviews committed snapshots, not uncommitted edits. If the intended change is still uncommitted, obtain authority for the needed snapshot or agree another review method. Do not commit merely to satisfy this guide.</p><p>Find the real specification rather than inventing one. If the user confirms none exists, report the skipped Spec axis. If reviewer capabilities are unavailable, disclose the blocker and agree an alternative rather than pretend the two-axis review ran.</p><p>See <a href="/projects/ai-skills/workflows/review-against-standards-and-spec.html">Review a fixed diff from two perspectives</a>.</p><h2 id="learn-from-completed-work" tabindex="-1">Learn from completed work <a class="header-anchor" href="#learn-from-completed-work" aria-label="Permalink to &quot;Learn from completed work&quot;">​</a></h2><p>Use <a href="/projects/ai-skills/skills/retro.html"><code>retro</code></a> after a bounded period with enough evidence to examine its process.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Session evidence and check results</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>retro: inspect problems and causes</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Recommend bounded improvements</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Stop for owner selection</span></span></code></pre></div><p>Distinguish lasting lessons from one-off friction. Stop at recommendations. An instruction change follows its own approval process, not automatic editing during a retrospective.</p><p>See <a href="/projects/ai-skills/workflows/learn-from-completed-work.html">Turn a completed issue into a small improvement</a>.</p><h2 id="diagrams-and-writing-aids" tabindex="-1">Diagrams and writing aids <a class="header-anchor" href="#diagrams-and-writing-aids" aria-label="Permalink to &quot;Diagrams and writing aids&quot;">​</a></h2><p>Use a diagram only when it answers the reader&#39;s relationship question. Choose <a href="/projects/ai-skills/workflows/explain-with-archify.html">interactive HTML with Archify</a> or <a href="/projects/ai-skills/workflows/draw-with-excalidraw.html">an editable image with Excalidraw</a> according to the needed output and available tools.</p><p>For prose, <a href="/projects/ai-skills/workflows/shorten-without-loss.html">shorten without losing meaning</a>. Keep precise identifiers, conditions, warnings, and complete instructions.</p><p>Agent-facing guidance has a separate audience. Use <a href="/projects/ai-skills/workflows/write-agent-facing-guidance.html">write guidance for an agent reader</a> for skills and instructions, rather than treating every project documentation page as agent policy.</p><p>When instruction routes or dependency metadata drift, use <a href="/projects/ai-skills/workflows/repair-instruction-routes.html">repair instruction drift through exact approval</a>. Investigating a mismatch does not authorize changing policy.</p>`,37)])])}const f=a(o,[["render",n]]);export{u as __pageData,f as default};
